    )
    ranks = {index: rank for rank, (index, _) in enumerate(ranked, 1)}

    rows = []
    for index, (scenario, n, states, lo_sum, hi_sum) in enumerate(collected):
        if n < minimum:
            interval = None
            state = None
            rank = None
        else:
            lo = lo_sum / n
            hi = hi_sum / n
            interval = [_round_output(lo), _round_output(hi)]
            if hi <= tolerance:
                state = "stable"
            elif lo > tolerance:
                state = "divergent"
            else:
                state = "uncertain"
            rank = ranks[index]
